INSERT IGNORE INTO `current_affairs` (`id`, `title`, `summary`, `key_points`, `content`, `why_it_matters`, `image_url`, `category`, `exam_tags`, `tags`, `source_url`, `published_date`, `is_published`, `is_featured`, `created_by`, `created_at`, `updated_at`) VALUES
  ('f0e488b9-cdab-4078-9b17-ce60b5a2a72c', 'India Hosts 18th BRICS Summit 2026 in New Delhi — New Delhi Declaration Adopted', 'India chaired the 18th BRICS Summit on September 12-13, 2026 at Bharat Mandapam, New Delhi. New Delhi Declaration adopted on Global South cooperation, de-dollarization, and reformed multilateralism.', '["Theme: Building for Resilience, Innovation, Cooperation and Sustainability","Hosted at Bharat Mandapam, New Delhi, September 12-13, 2026","India holds 2026 BRICS Presidency (Jan-Dec 2026)","New Delhi Declaration: Trade in local currencies, Digital public infrastructure, Green energy cooperation","9 BRICS partner nations participated alongside 5 full members"]', 'India hosted the 18th BRICS Summit at Bharat Mandapam, New Delhi on September 12-13, 2026 under India\'s 2026 BRICS Presidency.
